def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 10)
    grid_height = observation.get("grid_height", 10)

    # Defensive access for environment-specific targets
    def get_targets():
        if env == "pursuit_evasion":
            return [observation.get("opponent_position")]
        elif env == "territory_control":
            return observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        elif env == "resource_collection":
            return observation.get("resources") or []
        else:
            return []

    # Helper to determine move towards a target
    def move_towards(target):
        if not target:
            return 0, 0
        dx = 0
        dy = 0
        if target[0] > sx:
            dx = 1
        elif target[0] < sx:
            dx = -1
        if target[1] > sy:
            dy = 1
        elif target[1] < sy:
            dy = -1
        return dx, dy

    # Pursuit/Evasion logic
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            # Chase opponent
            return list(move_towards([ox, oy]))
        else:
            # Evade: move away from opponent
            dx = 0
            dy = 0
            if ox != sx:
                dx = -1 if ox > sx else 1
            if oy != sy:
                dy = -1 if oy > sy else 1
            return [dx, dy]

    targets = get_targets()
    if targets:
        # Choose closest target
        target = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        dx, dy = move_towards(target)
    else:
        # Default to moving towards opponent or stay
        dx = 0
        dy = 0
        if ox != sx:
            dx = 1 if ox > sx else -1
        if oy != sy:
            dy = 1 if oy > sy else -1

    # Ensure moves are in [-1, 1]
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]

